var $=jQuery.noConflict();$(document).ready(function(){$("#view-transaction-table").DataTable({order:[[0,!1]]}),$("#view-payouts-table").DataTable({order:[[0,"desc"]],rowGroup:{dataSrc:3}}),$("#view-payouts-table .custom-update").on("click",function(){var t,e=$(".admin-ajax-url").val(),i=$(this).parent().siblings("td.unique-id").text(),n=$(this).parent().siblings(".updated-status").find("select.payout-status-selection").val();"paid"==n?(t=prompt("Invoice ID"))?$.ajax({url:e,data:{action:"admin_payout_management",unique_id:i,invoice_id:t,status:n},success:function(a){$.ajax({url:e,data:{action:"send_payout_email",unique_id:i,status:n,invoice_id:t},success:function(a){}}),window.location.reload()}}):alert("Please add invoice ID"):alert("Please change the status to paid")})});